"""Render a static English report from the executed results; no invented outcomes."""
from pathlib import Path
import html,json
from collections import defaultdict
R=Path(__file__).resolve().parent
d=json.loads((R/'data/results.json').read_text());rows=d['rows'];p=d['plan'];v=d['environment']
esc=lambda s:html.escape(str(s),quote=True)
labels={'original':'Clear original','low-resolution':'Reduced resolution','skewed':'Skewed +3°'}
by=defaultdict(list)
for r in rows:by[r['condition']].append(r)
pooled={c:100*sum(x['character_errors'] for x in rs)/sum(x['reference_characters'] for x in rs) for c,rs in by.items()}
totalchars=sum(r['reference_characters'] for r in by['original'])
lead='; '.join(f"{labels[c].lower()}: {pooled[c]:.2f}%" for c in labels)
interpretations=[]
for condition in ('low-resolution','skewed'):
    changes=[r['character_errors']-next(x['character_errors'] for x in by['original'] if x['sample']==r['sample']) for r in by[condition]]
    comparison='more' if all(x>0 for x in changes) else 'no more' if all(x<=0 for x in changes) else 'different numbers of'
    interpretations.append(f"{labels[condition]} produced {comparison} character errors than the clear original across the three paired samples. The pooled CER was {pooled[condition]:.2f}%, compared with {pooled['original']:.2f}% for the originals.")
table=''
for r in rows:
    example=r['example']
    ex='No character edits after whitespace normalization.' if not example else f"{example['type']}: {repr(example['reference'])} → {repr(example['ocr'])}"
    table+=f'''<tr><th scope="row">{r['sample']}</th><td>{labels[r['condition']]}</td><td>{r['width']} × {r['height']}</td><td>{r['angle_degrees']}°</td><td>{r['character_errors']}<small>S {r['substitutions']} / D {r['deletions']} / I {r['insertions']}</small></td><td>{r['reference_characters']}</td><td>{r['cer_percent']:.2f}%</td><td>{esc(ex)}</td></tr>'''

# A grouped horizontal comparison has one shared linear axis beginning at zero.
maximum=max(1,max(r['cer_percent'] for r in rows)); maximum=(int(maximum/5)+1)*5
parts=['<svg viewBox="0 0 900 430" role="img" aria-labelledby="ct cd"><title id="ct">Character error rate for each sample and condition</title><desc id="cd">Nine measured CER values in percent, with one shared linear scale starting at zero. Exact edit counts are in the table.</desc>']
colors={'original':'#153f64','low-resolution':'#ba4a26','skewed':'#0b776b'}
for i,c in enumerate(labels):
    x=18+i*260;parts.append(f'<rect x="{x}" y="12" width="14" height="14" fill="{colors[c]}"/><text x="{x+22}" y="24">{labels[c]}</text>')
for i in range(6):
    x=135+i*124;parts.append(f'<line x1="{x}" y1="48" x2="{x}" y2="375" stroke="#dbe3e8"/><text x="{x}" y="402" text-anchor="middle">{maximum*i/5:g}%</text>')
for i,sample in enumerate(('A','B','C')):
    top=65+i*105;parts.append(f'<text x="18" y="{top+33}" font-weight="700">Sample {sample}</text>')
    for j,c in enumerate(labels):
        r=next(x for x in rows if x['sample']==sample and x['condition']==c)
        width=r['cer_percent']/maximum*620;y=top+j*24
        parts.append(f'<rect x="135" y="{y}" width="{width:.3f}" height="17" fill="{colors[c]}"/><text x="{145+width:.3f}" y="{y+14}">{r["cer_percent"]:.2f}%</text>')
parts.append('</svg>');chart=''.join(parts)

gallery=''
for sample in ('A','B','C'):
    gallery+=f'<h3>Sample {sample}</h3><div class="gallery">'
    for r in [x for x in rows if x['sample']==sample]:
        gallery+=f'''<figure><figcaption><strong>{labels[r['condition']]}</strong><br>{r['width']} × {r['height']} pixels · {r['angle_degrees']}°</figcaption><a href="{r['image']}"><img src="{r['image']}" width="{r['width']}" height="{r['height']}" loading="lazy" alt="Actual OCR input: sample {sample}, {esc(labels[r['condition']])}"></a><p class="links"><a href="{r['image']}">Full image</a> · <a href="{r['raw_text']}">Raw OCR text</a></p></figure>'''
    gallery+='</div>'

examples=''
for r in rows:
    e=r['example']
    if e:
        examples+=f'''<article class="example"><h3>{r['sample']} · {labels[r['condition']]}</h3><p>First edit in the recorded minimum-distance alignment: <code>{esc(e['type'])}</code>, reference character {e['reference_index']+1}. An empty string means a missing or added character.</p><div class="comparison"><div><strong>Reference context</strong><pre>{esc(e['reference_context'])}</pre></div><div><strong>OCR context</strong><pre>{esc(e['ocr_context'])}</pre></div></div><p><code>{esc(repr(e['reference']))}</code> → <code>{esc(repr(e['ocr']))}</code>. <a href="{r['raw_text']}">Raw output</a> · <a href="{r['normalized_text']}">Scored output</a></p></article>'''
    else:
        examples+=f'''<p><strong>{r['sample']} · {labels[r['condition']]}:</strong> no character edits after the stated whitespace normalization. <a href="{r['raw_text']}">Inspect the unchanged raw output</a>.</p>'''
canonical=(R/'canonical.txt').read_text().strip() if (R/'canonical.txt').exists() else ''
canonical_tag=f'<link rel="canonical" href="{esc(canonical)}">' if canonical else ''
text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>How Image Quality Affects OCR: A Small Reproducible Test</title><meta name="description" content="Nine actual Tesseract OCR runs compare clear, downsampled and tilted English text images, with raw outputs, character error rates and reproducible sources.">{canonical_tag}<meta name="robots" content="index,follow"><meta name="color-scheme" content="light">
<style>
*{{box-sizing:border-box}}body{{margin:0;color:#182f42;background:white;font:17px/1.7 system-ui,-apple-system,Segoe UI,sans-serif}}main{{max-width:1100px;margin:auto;padding:40px 28px 65px}}header{{border-top:6px solid #0b776b;padding-top:24px;max-width:920px}}.eyebrow{{font-size:13px;letter-spacing:.1em;font-weight:700;text-transform:uppercase;color:#4d6877}}h1{{font-size:clamp(32px,4.6vw,52px);line-height:1.13;letter-spacing:-.03em;margin:18px 0 22px}}h2{{font-size:28px;line-height:1.25;margin:0 0 18px}}h3{{font-size:20px;line-height:1.4;margin:26px 0 12px}}p{{max-width:850px;margin:0 0 18px}}section{{border-top:1px solid #dbe3e8;padding-top:28px;margin-top:42px}}a{{color:#075e9b;text-underline-offset:3px;overflow-wrap:anywhere}}.lede{{font-size:21px}}.byline,.note,.links,figcaption,small{{font-size:14px;color:#506879}}.finding{{background:#eff6f5;border-left:4px solid #0b776b;padding:22px;margin:26px 0}}.finding p:last-child{{margin:0}}.scroll{{overflow-x:auto;border:1px solid #dbe3e8;border-radius:5px}}table{{min-width:1000px;width:100%;border-collapse:collapse;font-size:14px;line-height:1.5}}th,td{{text-align:left;vertical-align:top;padding:13px;border-bottom:1px solid #dbe3e8}}thead{{background:#eff4f7}}small{{display:block;white-space:nowrap;font-size:12px}}caption{{text-align:left;padding:14px;font-weight:600}}.chart{{overflow-x:auto}}svg{{width:100%;min-width:720px;height:auto;margin:18px 0;display:block}}svg text{{font:14px system-ui,sans-serif;fill:#182f42}}.gallery{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}}figure{{margin:0}}figure img{{width:100%;height:auto;border:1px solid #dbe3e8;display:block;margin:10px 0}}figure p{{margin-bottom:0}}.comparison{{display:grid;grid-template-columns:1fr 1fr;gap:18px}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;background:#eff4f7;padding:15px;font:15px/1.6 ui-monospace,Consolas,monospace;border:1px solid #dbe3e8}}code{{font:14px/1.6 ui-monospace,Consolas,monospace;background:#eff4f7;padding:2px 4px;overflow-wrap:anywhere}}.example{{border-top:1px solid #dbe3e8;padding-top:8px;margin-top:24px}}li{{max-width:850px;margin:9px 0}}details{{padding:17px;background:#eff4f7;margin:20px 0}}summary{{cursor:pointer;font-weight:650}}footer{{border-top:2px solid #0b776b;margin-top:45px;padding-top:22px;font-size:14px;color:#506879}}@media(max-width:650px){{main{{padding:22px 18px 40px}}.gallery,.comparison{{grid-template-columns:1fr}}h2{{font-size:25px}}.lede{{font-size:19px}}.finding{{padding:16px}}}} </style></head><body><main>
<header><div class="eyebrow">Idraaak · OCR Image Quality Lab</div><h1>How Image Quality Affects OCR: A Small Reproducible Test</h1><p class="lede">The same text can produce different recognition errors after a change in image quality. Here are all nine results from three original English passages, one font, and one fixed Tesseract configuration.</p><p class="byline">Published by Nedal / Idraaak · Experiment design: 17 October 2026 · Synthetic samples · AI-assisted code, analysis and writing</p></header>
<div class="finding"><p><strong>Measured pooled character error rates:</strong> {lead}.</p><p>These are edit-distance measurements against known source text, not the engine’s confidence scores. Each condition contains the same three passages and {totalchars:,} reference characters in total. Lower CER means fewer edits were needed.</p></div>
<section id="question"><h2>What can a smaller or tilted image change?</h2><p>OCR turns pixels into characters, so a readable-looking preview is not enough to establish that the extracted words are correct. This test asks how the character edit count changes when resolution is reduced or the page is tilted, while the text, font, contrast, recognition engine and command settings stay fixed.</p><p>The experiment is deliberately small. It measures these nine inputs rather than estimating the accuracy of OCR in general.</p></section>
<section id="method"><h2>A fixed design, chosen before the main runs</h2><p>Samples A, B and C contain 93, 95 and 94 words respectively. They are original fictional passages about a workshop, a garden notebook and an archive. Their <a href="texts.json">original texts</a> are the ground truth; none contains personal records.</p><ul><li><strong>Clear originals:</strong> 1600 × 1000 grayscale pixels, black text on white, DejaVu Sans 2.37 regular at 32 pixels, 80-pixel margins and 48-pixel line spacing. Wrapping is based on the same font’s measured pixel width. No text comes from an image generator.</li><li><strong>Reduced resolution:</strong> resize each complete original to 400 × 250 with Pillow LANCZOS: one quarter of each dimension and one sixteenth of the pixels. No extra sharpening or thresholding.</li><li><strong>Skewed:</strong> rotate each original counterclockwise by 3° with BICUBIC interpolation and an expanded white canvas. Expansion keeps the whole source image, including every line, within the frame. Rotation necessarily adds border space and resamples edges; it is not a pure change to angle at the pixel level.</li></ul><p>All nine files are lossless PNGs. Nominal DPI metadata and the OCR <code>--dpi 300</code> argument are identical for all conditions, so the reduced image genuinely has fewer pixels per character rather than a different OCR DPI setting. The <a href="plan.json">design file</a> was committed before the first main OCR run. There was no search across settings after inspecting the errors.</p>
<p><strong>Engine:</strong> {esc(v['tesseract_version'].splitlines()[0])}, English only, LSTM engine mode 1, page segmentation mode 6 (one uniform block of text), one CPU thread. It runs as a local command-line program on a GitHub Actions Ubuntu 24.04 runner; no external OCR API is called. The same bundled English model and command options are used for every image. The operating system, package versions, font hash, model hash and full engine version are in <a href="data/environment.json">the environment record</a>.</p><pre>tesseract images/A-original.png raw/A-original \\
  --tessdata-dir models -l eng --oem 1 --psm 6 --dpi 300</pre><p>Only the input and output file names change between runs. Tesseract still performs its own internal processing; this test does not claim to disable internal skew handling or binarization.</p></section>
<section id="measure"><h2>How the character error rate was calculated</h2><p>For scoring, every run of whitespace is replaced by one ASCII space and leading/trailing whitespace is removed. That treats OCR line wrapping as layout, not a character error. Case, punctuation, digits and every other non-whitespace code point are preserved. Nothing is corrected by hand, and no punctuation is removed to improve a score.</p><p><strong>CER = (substitutions + deletions + insertions) ÷ characters in the normalized reference.</strong> Spaces remaining after normalization count in that denominator. The numerator is the minimum unit-cost Levenshtein edit distance. The stored alignment uses substitution, deletion, then insertion as its deterministic tie preference; another minimum alignment can assign edits differently without changing the total.</p><p>The pooled rates sum edit counts across A, B and C, then divide by the summed reference length. They are not an unweighted average of the three percentages. CER is an error rate and can exceed 100% when insertions are numerous; it is not a confidence score.</p></section>
<section id="results"><h2>All nine measured results</h2><p class="note">On a narrow screen, scroll the table and chart within their frames. S = substitution, D = deletion, I = insertion. Percentages are rounded to two decimals; counts and denominators are exact.</p><div class="scroll"><table><caption>All samples and conditions · no omitted runs</caption><thead><tr><th>Sample</th><th>Condition</th><th>Image pixels</th><th>Angle</th><th>Character errors</th><th>Reference characters</th><th>CER</th><th>First actual edit</th></tr></thead><tbody>{table}</tbody></table></div><div class="chart">{chart}</div><p><a href="data/results.csv">Download CSV</a> · <a href="data/results.json">Full results JSON</a> · <a href="data/edit-operations.json">Every character edit</a></p></section>
<section id="images"><h2>The actual OCR inputs</h2><p>These are the files supplied to Tesseract, not recreated screenshots. Each preview links to the full image. Thumbnail scaling can hide differences, so open the original pixel dimensions when judging small letters.</p>{gallery}</section>
<section id="examples"><h2>What the engine actually returned</h2><p>The examples below come directly from the scored outputs. They show the first edit’s surrounding text when an error occurred, and explicitly identify runs with no edits. Raw files preserve Tesseract’s uncorrected line breaks; the scored copies apply only the whitespace rule above.</p>{examples}</section>
<section id="meaning"><h2>What these inputs show—and what they cannot</h2>{''.join('<p>'+esc(x)+'</p>' for x in interpretations)}<p>Resolution reduction removes pixel information; rotating an image changes the alignment of its text lines and resamples letter edges. Those mechanisms are consistent with Tesseract’s official quality guidance, but the size and even direction of the measured effects here belong to these particular passages and settings.</p><p>There are only three artificial English texts, one regular font, one layout and one engine/model combination. The experiment does not test Arabic, handwriting, photographs, shadows, compression artifacts, complex columns or tables. It does not isolate every internal OCR processing step, compare OCR products, establish statistical reliability across documents, or identify a universally safe size or skew threshold.</p></section>
<section id="practice"><h2>A practical extraction workflow</h2><ol><li><strong>Keep a detailed source image.</strong> Tesseract’s documentation recommends adequate resolution and discusses the importance of character size. Merely changing a DPI label cannot restore pixels already discarded.</li><li><strong>Keep text lines level when possible.</strong> Its official guide recommends deskewing when tilt interferes with line segmentation. This experiment uses one 3° angle, not a universal cutoff.</li><li><strong>Match the layout setting to the input.</strong> Mode 6 was chosen because these samples are a single text block. It should not be treated as the best mode for an arbitrary full page.</li><li><strong>Check the extracted characters.</strong> Compare a few lines against the source, especially numbers, punctuation and names. A low average error rate can still conceal a wrong value in an important field.</li></ol><p>When choosing a desktop workflow, look for controls that let you retain the source image, select the correct language and inspect the extracted text. Readers who prefer an Arabic overview of available options can consult Idraaak’s guide to <a href="https://idraaak.com/برنامج-تحويل-الصورة-الى-نص-للكمبيوتر/" lang="ar" dir="rtl">تحويل الصورة إلى نص للكمبيوتر</a>. That Arabic companion is from the same publisher as this report; it supplies neither these measurements nor the Tesseract documentation. The programs mentioned there were not tested in this experiment.</p></section>
<section id="reproduce"><h2>Reproduce the experiment</h2><p>The <a href="https://github.com/nedal-dev/ocr-image-quality-lab">public repository</a> contains the frozen design, original texts, image generator, OCR commands, raw outputs, normalized scoring texts, CSV, edit alignments and the report builder. It also includes the font and language model with their respective license notices. Input and output file hashes are recorded in <a href="data/manifest.json">the evidence manifest</a>.</p><pre>python -m pip install -r requirements.txt
python experiment.py
python build_report.py</pre><p>Install the exact free Ubuntu packages listed in <a href="README.md">README</a> first. The command-line engine stays fixed at 5.3.4. Rerunning with a different renderer, font, model or engine can change pixels or outputs, so compare their recorded hashes before attributing a change solely to image quality.</p></section>
<section id="sources"><h2>Technical references</h2><ul><li><a href="https://tesseract-ocr.github.io/tessdoc/ImproveQuality.html">Tesseract: improving output quality</a> — resolution, skew, borders and segmentation guidance.</li><li><a href="https://tesseract-ocr.github.io/tessdoc/Command-Line-Usage.html">Tesseract: command-line usage</a> — language and OCR engine options.</li><li><a href="https://dejavu-fonts.github.io/License.html">DejaVu font license</a> — redistribution and copyright conditions.</li></ul></section>
<footer><p>Publisher: Nedal / Idraaak. The synthetic texts, code, analysis and report were created with AI assistance. No independent human review or affiliation with Tesseract or Posit is claimed.</p><p>Original project code, report text and synthetic samples: <a href="LICENSE">MIT License</a>. DejaVu and Tesseract language data retain their own notices in fonts/ and models/.</p></footer></main></body></html>'''
(R/'index.html').write_text(text,encoding='utf-8')
print(json.dumps({'report_characters':len(text),'pooled_cer_percent':pooled},indent=2))
